import{_ as s,o as a,c as i,ag as n}from"./chunks/framework.BSsJcWLc.js";const g=JSON.parse('{"title":"Processing Layer","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/processing-layer.md","filePath":"architecture/processing-layer.md"}'),t={name:"architecture/processing-layer.md"};function o(r,e,d,l,p,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="processing-layer" tabindex="-1">Processing Layer <a class="header-anchor" href="#processing-layer" aria-label="Permalink to &quot;Processing Layer&quot;">​</a></h1><p>Runs processing modes that classify signals or extract features. Modes run independently or together.</p><p>All consumers read from shared memory ring buffers written by DAQ. Each mode runs as an independent process with its own buffer and per-mode preprocessing. Outputs flow through FanOutQueue to MetricsSaver and the WebSocket visualization bridge.</p><p><strong>Processing Flow:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DAQ → SharedRingBuffer (per stream, zero-copy shared memory)</span></span>
<span class="line"><span>            ↑ read_new()</span></span>
<span class="line"><span>            ├─ SynchronousMode  (event-driven training)</span></span>
<span class="line"><span>            ├─ AsynchronousMode (continuous inference)</span></span>
<span class="line"><span>            ├─ NeurofeedbackMode (band power extraction)</span></span>
<span class="line"><span>            ├─ DataSaver         (SWMR HDF5 for archival + online training)</span></span>
<span class="line"><span>            └─ run_visualization_bridge() (WebSocket broadcast + quality monitoring)</span></span></code></pre></div><hr><h2 id="data-distribution" tabindex="-1">Data Distribution <a class="header-anchor" href="#data-distribution" aria-label="Permalink to &quot;Data Distribution&quot;">​</a></h2><p>DAQ writes raw samples (all channels + markers column) to one <code>SharedRingBuffer</code> per stream type (see <strong><a href="./data-layer.html#shared-ring-buffer">SharedRingBuffer</a></strong>). All consumers connect to the same buffer and read independently -- zero-copy, no serialization.</p><p><code>PipelineOrchestrator</code> (<code>src/dendrite/processing/orchestrator.py</code>) creates ring buffers, passes names + channel maps to every consumer, and manages pipeline subprocess lifecycle.</p><p><strong>Channel Maps</strong></p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;buffer_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dendrite_rb_eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># derived from stream_key</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;modalities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">61</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">62</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">63</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># column indices by channel type</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;modality_labels&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eeg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Fp1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VEOG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HEOG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;marker_col&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># last column</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;sample_rate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>All consumers use this map to slice columns from the shared data array.</p><hr><h2 id="preprocessing" tabindex="-1">Preprocessing <a class="header-anchor" href="#preprocessing" aria-label="Permalink to &quot;Preprocessing&quot;">​</a></h2><p>OnlinePreprocessor (<code>src/dendrite/processing/preprocessing/preprocessor.py</code>) applies modality-specific filtering without modifying raw storage.</p><p>Runs <strong>inside each mode</strong> (not centrally). BaseMode lazily creates the preprocessor on first sample, using actual channel counts. CAR operates on all channels before channel selection narrows to the mode&#39;s subset.</p><p><strong>Per-Mode Lifecycle:</strong></p><ol><li><code>_setup_preprocessor()</code> — reads config, creates <code>SamplePreprocessor</code> (<code>mode_utils.py</code>)</li><li><code>SamplePreprocessor._ensure_preprocessor(data_dict)</code> — lazily creates <code>OnlinePreprocessor</code> on first sample using actual channel counts</li><li><code>_preprocess_sample(sample)</code> — delegates to <code>SamplePreprocessor</code>, applies preprocessing on all channels, then selects subset</li></ol><p><strong>Modality Processors</strong></p><p>Single <code>ModalityProcessor</code> class with config-driven behavior: bandpass filter (lowcut/highcut/filter_order), notch filter (line_freq/notch_width), common average reference (apply_rereferencing), interpolation (channel_labels), and anti-aliased downsampling (downsample_factor). Omitting filter keys gives passthrough. Markers bypass preprocessing. <code>ChannelScaler</code> (<code>preprocessing/scalers.py</code>) provides optional per-channel z-score normalization.</p><p><strong>Bad Channel Detection &amp; Interpolation</strong></p><p><code>ChannelQualityMonitor</code> (MAD-based z-score with hysteresis) runs in the visualization bridge. After 10s warmup, the bad channel list is frozen and a correlation-based interpolation matrix W is precomputed from the warmup data&#39;s pairwise Pearson correlations. Applied per-chunk as <code>data[bad] = W @ data[good]</code> before CAR. No montage or 3D electrode positions required.</p><p>Operators can manually flag/unflag channels via dashboard. Manual flags merge with auto-detected: <code>effective_bad = (auto UNION flagged) MINUS unflagged</code>. Changes trigger W recomputation via <code>interp_version</code> in SharedState.</p><p>Interpolation pipeline:</p><ol><li><strong>Detection</strong>: <code>ChannelQualityMonitor</code> on raw signal data (rolling 5s window, iterative MAD z-score, hysteresis)</li><li><strong>Freeze</strong>: After 10s warmup, list locked. Override via <code>PUT /api/pipeline/channel-flags</code></li><li><strong>Interpolation</strong>: <code>CorrelationInterpolationMatrix</code> computes W from pairwise channel correlations in warmup data. <code>InterpolationApplicator</code> applies W per chunk before CAR</li><li><strong>Training parity</strong>: <code>load_recording_epochs()</code> applies the same interpolation to raw HDF5 data before offline preprocessing</li></ol><p>Processing order per chunk: <strong>interpolate bad channels → CAR (all channels) → bandpass filter → downsample</strong></p><p><strong>Epoch Quality Control</strong></p><p><code>EpochQualityChecker</code> (<code>src/dendrite/data/quality.py</code>) rejects epochs with NaN/Inf, flat signals (variance &lt; 1e-12), or extreme outliers (MAD z-score &gt; 50). Applied by <code>RawData.epoch()</code> (enabled by default).</p><p><strong>Preprocessing Parity</strong></p><p>OnlinePreprocessor uses causal IIR filtering (<code>scipy.signal.lfilter</code> with state preservation) for both:</p><ul><li><strong>Online</strong>: sample-by-sample processing with maintained filter state</li><li><strong>Offline</strong>: <code>apply_preprocessing_offline()</code> (<code>preprocessing/offline_adapter.py</code>) processes data in chunks (default 250 samples), simulating online streaming. Used by MLService when loading training data.</li></ul><hr><h2 id="processing-modes" tabindex="-1">Processing Modes <a class="header-anchor" href="#processing-modes" aria-label="Permalink to &quot;Processing Modes&quot;">​</a></h2><p>Each mode can be powered by a Decoder that wraps a predictive Model. Modes are independently optional and can run concurrently. All inherit from BaseMode (<code>src/dendrite/processing/modes/base_mode.py</code>) and run as independent <code>multiprocessing.Process</code> instances.</p><p><strong>Data Flow</strong></p><p>Each mode reads samples from its assigned ring buffer via <code>_get_next_sample()</code>. Samples arrive as dicts with dynamic modality keys (e.g. <code>&#39;eeg&#39;</code>, <code>&#39;emg&#39;</code>) containing <code>(n_channels, 1)</code> arrays, plus <code>&#39;markers&#39;</code> and timestamps. Modality keys come from the channel map — not hardcoded.</p><p>Samples accumulate in <code>Buffer</code> (per-modality deques), which provides <code>extract_window()</code> for continuous inference and <code>extract_epoch_at_event()</code> for event-locked epochs. Outputs route through <code>FanOutQueue</code> to MetricsSaver and the visualization bridge — dropped (not blocked) if queues are full.</p><p>Source: <code>src/dendrite/processing/modes/base_mode.py</code>, <code>src/dendrite/processing/modes/mode_utils.py</code></p><hr><h2 id="synchronousmode" tabindex="-1">SynchronousMode <a class="header-anchor" href="#synchronousmode" aria-label="Permalink to &quot;SynchronousMode&quot;">​</a></h2><p>SynchronousMode (<code>src/dendrite/processing/modes/synchronous_mode.py</code>) collects event-locked epochs and trains models online.</p><p>Monitors event markers to extract time-locked windows (default 0.0-2.0s post-stimulus, configurable via <code>epoch_tmin</code>/<code>epoch_tmax</code>). Training triggered at configurable intervals (e.g., every 10 epochs) via <code>training_queue</code> -- MLService pulls epoch data from SWMR HDF5.</p><p><strong>Output:</strong> Predictions with confidence, accuracy, Cohen&#39;s kappa, and averaged ERP waveforms per event type.</p><hr><h2 id="asynchronousmode" tabindex="-1">AsynchronousMode <a class="header-anchor" href="#asynchronousmode" aria-label="Permalink to &quot;AsynchronousMode&quot;">​</a></h2><p>AsynchronousMode (<code>src/dendrite/processing/modes/asynchronous_mode.py</code>) applies pre-trained decoders continuously for real-time BCI control.</p><p>Processes sliding windows at regular intervals. Supports decoder hot-swapping from linked SynchronousMode or disk. Polls SharedState ~1Hz for new decoders, loads in background thread. When ground truth events are available, temporal evaluation calculates accuracy with separate background handling.</p><p><strong>Output:</strong> Predictions with confidence, accuracy metrics when ground truth available.</p><hr><h2 id="neurofeedbackmode" tabindex="-1">NeurofeedbackMode <a class="header-anchor" href="#neurofeedbackmode" aria-label="Permalink to &quot;NeurofeedbackMode&quot;">​</a></h2><p>NeurofeedbackMode (<code>src/dendrite/processing/modes/neurofeedback_mode.py</code>) extracts spectral band power.</p><p>Sliding windows with Welch&#39;s method per channel, extracting power in configurable frequency bands (alpha, beta, SMR, etc.). Optional baseline normalization (percent-change) and channel clustering for regional feedback.</p><p><strong>Output:</strong> Per-channel band power per frequency band, sent to both <code>prediction_queue</code> and <code>output_queue</code>.</p><hr><h2 id="visualization-bridge" tabindex="-1">Visualization Bridge <a class="header-anchor" href="#visualization-bridge" aria-label="Permalink to &quot;Visualization Bridge&quot;">​</a></h2><p><code>run_visualization_bridge()</code> (<code>src/dendrite/web/ws/visualization_bridge.py</code>) reads raw signal data from the primary stream&#39;s ring buffer, preprocesses, monitors quality, and broadcasts via QueueBridge.</p><p><strong>Raw Data Path:</strong></p><ol><li>Reads from stream ring buffer (zero-copy)</li><li>Applies CAR + bandpass</li><li>Publishes channel quality to SharedState every 2s</li><li>Decimates to ~100 Hz before WebSocket broadcast</li><li>Events bypass decimation to preserve timing</li></ol><p><strong>Mode Output Path:</strong> Drains <code>visualization_queue</code> and broadcasts to <code>mode_data</code> WebSocket channel.</p><p><strong>Architecture:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SharedRingBuffer ──► VizBridge ──► QueueBridge ──► /ws/visualization (raw signal data)</span></span>
<span class="line"><span>                     (preproc +     (msgpack)</span></span>
<span class="line"><span>                      quality)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>visualization_queue ──► VizBridge ──► QueueBridge ──► /ws/mode_data (mode outputs)</span></span></code></pre></div><p>The bridge reconfigures preprocessing dynamically when settings change during recording.</p><p><strong>Generic Output Streamers</strong></p><p>Alternative output protocols inheriting from <code>BaseOutputStreamer</code> (<code>src/dendrite/data/streaming/</code>):</p><table tabindex="0"><thead><tr><th>Streamer</th><th>Protocol</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>LSLStreamer</strong></td><td>Generic LSL</td><td>Configurable LSL output for custom applications</td></tr><tr><td><strong>SocketStreamer</strong></td><td>TCP/UDP</td><td>Low-latency local networking (Python/MATLAB clients)</td></tr><tr><td><strong>ZMQStreamer</strong></td><td>ZeroMQ</td><td>High-performance pub/sub for distributed systems</td></tr><tr><td><strong>ROS2Streamer</strong></td><td>ROS2 Topics</td><td>Robotic control integration (wheelchair, prosthetics, exoskeletons)</td></tr></tbody></table><p>Each streamer runs in a separate process, consuming mode output queues asynchronously.</p><hr><p><strong>Related Documentation:</strong></p><ul><li><strong><a href="./ml-layer.html">ML Layer</a></strong> — Decoders, models, and training infrastructure</li><li><strong><a href="./data-layer.html">Data Layer</a></strong> — Data acquisition, ring buffers, and storage</li><li><strong><a href="./web-layer.html">Web Layer</a></strong> — WebSocket bridge, frontend architecture</li></ul>`,69)])])}const u=s(t,[["render",o]]);export{g as __pageData,u as default};
